    certifications: ['CERTIFIED FINANCIAL PLANNER™ professional (CFP®)', 'Chartered Retirement Planning Counselor℠ (CRPC®)', 'Retirement Income Certified Professional® (RICP®)', 'Certified Divorce Financial Analyst (CDFA®)'],
    social: { linkedin: 'https://www.linkedin.com/in/margueritacheng/', x: 'https://x.com/blueoceangw' },
