function toPayload(a, index) {
  const payload = {
    name: a.name,
    slug: a.slug,
    title: a.title,
    bio: a.bio,
    expertise: a.expertise && a.expertise.length ? a.expertise : undefined,
    education: a.education && a.education.length ? a.education : undefined,
    certifications: a.certifications && a.certifications.length ? a.certifications : undefined,
    social: a.social && Object.keys(a.social).length ? a.social : undefined,
    seoMetadata: a.seo ? { title: a.seo.title, description: a.seo.description, keywords: a.seo.keywords } : undefined,
    sortOrder: index + 1,
  };
  if (a.credentials) payload.credentials = a.credentials;
  if (a.videoUrl) payload.videoUrl = a.videoUrl;
  // avatarUrl intentionally omitted for every author — no verified photo supplied.
  return payload;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function req(method, url, token, body, attempts = 5) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      const r = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
        body: body ? JSON.stringify(body) : undefined,
      });
      const data = await r.json().catch(() => ({}));
      if (r.status >= 500 && i < attempts - 1) { await sleep(400 * (i + 1)); continue; }
      return { status: r.status, data };
    } catch (e) {
      lastErr = e;
      await sleep(400 * (i + 1));
    }
  }
  throw lastErr || new Error('request failed after retries');
}

async function getToken() {
  if (CMS_TOKEN) return CMS_TOKEN;
  if (!PW) throw new Error('Set CMS_TOKEN (prod bearer) or SUPERADMIN_PASSWORD (local login) — see script header for usage.');
  const login = await req('POST', `${AUTH}/login`, null, { email: EMAIL, password: PW });
  const token = login.data?.data?.accessToken;
  if (!token) throw new Error('login failed: ' + JSON.stringify(login.data).slice(0, 200));
  return token;
}

async function main() {
  const payloads = AUTHORS.map(toPayload);

  if (DRY_RUN) {
    console.log(JSON.stringify({ ok: true, dryRun: true, site: SITE, base: BASE, count: payloads.length, payloads }, null, 2));
    return;
  }

  const token = await getToken();

  const existingRes = await req('GET', `${BASE}/authors`, token);
  const existing = new Set((existingRes.data?.data || []).map((a) => a.slug));

  let created = 0, skipped = 0, failed = 0;
  for (const payload of payloads) {
    if (existing.has(payload.slug)) { skipped++; continue; }
    const res = await req('POST', `${BASE}/authors`, token, payload);
    if (res.status === 201 || res.status === 200) created++;
    else if (res.status === 409) skipped++;
    else { failed++; console.error(`author ${payload.slug} -> ${res.status}`, JSON.stringify(res.data).slice(0, 300)); }
    await sleep(150);
  }

  console.log(JSON.stringify({ ok: true, site: SITE, base: BASE, created, skipped, failed, total: payloads.length }, null, 2));
}

main().catch((e) => { console.error('imperialpedia author seed failed:', e.message); process.exit(1); });
